private actor SchoolTypeStreamCursor {
    private var offset: Int
    private var remaining: Int?
    private var buffer: [SchoolType] = []
    private var index = 0
    private var finished = false
    private let fetch: @Sendable (Int, Int) async throws -> [SchoolType]

    init(offset: Int, remaining: Int?, fetch: @escaping @Sendable (Int, Int) async throws -> [SchoolType]) {
        self.offset = offset; self.remaining = remaining; self.fetch = fetch
    }

    func next() async throws -> SchoolType? {
        try _Concurrency.Task<Never, Never>.checkCancellation()
